"use client";

import "../../styles/teum-base.css";
import "../../styles/components/radar-chart.css";
import { useId, useMemo, type CSSProperties, type KeyboardEvent, type PointerEvent, type ReactNode } from "react";
import { formatAnalyticsValue, type AnalyticsSeriesTone } from "../../lib/analytics";
import { cn } from "../../lib/cn";
import { AnalyticsFrame, analyticsClassNames, getLinearAnalyticsKeyIndex, useAnalyticsActiveIndex } from "./analytics-frame";

export type RadarAxis = {
  id: string;
  label: string;
  max: number;
};

export type RadarSeries = {
  id: string;
  label: string;
  values: Readonly<Record<string, number | null>>;
  tone?: AnalyticsSeriesTone;
};

export type RadarChartProps = {
  title: string;
  description?: string;
  axes: readonly RadarAxis[];
  series: readonly RadarSeries[];
  className?: string;
  height?: number;
  valueFormatter?: (value: number, axis: RadarAxis, series: RadarSeries) => string;
  activeAxisIndex?: number | null;
  defaultActiveAxisIndex?: number | null;
  onActiveAxisIndexChange?: (index: number | null) => void;
  onAxisActivate?: (axis: RadarAxis, index: number) => void;
  loading?: boolean;
  empty?: ReactNode;
  error?: ReactNode;
  showDataByDefault?: boolean;
};

const radarBox = { width: 640, height: 260, centerX: 320, centerY: 126, radius: 88 } as const;
const radarTones: readonly AnalyticsSeriesTone[] = ["primary", "secondary", "tertiary"];

function radarPoint(index: number, length: number, ratio = 1) {
  const angle = -Math.PI / 2 + index / Math.max(1, length) * Math.PI * 2;
  return {
    x: radarBox.centerX + Math.cos(angle) * radarBox.radius * ratio,
    y: radarBox.centerY + Math.sin(angle) * radarBox.radius * ratio,
  };
}

function radarPolygon(values: readonly number[]) {
  return values.map((ratio, index) => {
    const point = radarPoint(index, values.length, Math.min(1, Math.max(0, ratio)));
    return `${point.x.toFixed(2)},${point.y.toFixed(2)}`;
  }).join(" ");
}

export function RadarChart({
  title,
  description,
  axes,
  series,
  className,
  height = 260,
  valueFormatter = (value) => formatAnalyticsValue(value),
  activeAxisIndex,
  defaultActiveAxisIndex = null,
  onActiveAxisIndexChange,
  onAxisActivate,
  loading = false,
  empty = "No dimensions for this comparison.",
  error,
  showDataByDefault = false,
}: RadarChartProps) {
  const id = useId();
  const validAxes = useMemo(() => axes.filter((axis) => Number.isFinite(axis.max) && axis.max > 0), [axes]);
  const { activeIndex: active, setActiveIndex, scheduleActiveIndex, clearActiveIndex } = useAnalyticsActiveIndex({
    length: validAxes.length,
    value: activeAxisIndex,
    defaultValue: defaultActiveAxisIndex,
    onChange: onActiveAxisIndexChange,
  });
  const activeAxis = active === null ? null : validAxes[active];
  const instructionsId = `${id}-instructions`;
  const renderedSeries = useMemo(() => series.map((item, seriesIndex) => ({
    ...item,
    tone: item.tone ?? radarTones[seriesIndex % radarTones.length],
    normalized: validAxes.map((axis) => {
      const value = item.values[axis.id];
      return typeof value === "number" && Number.isFinite(value) ? value / axis.max : 0;
    }),
  })), [series, validAxes]);

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (!validAxes.length) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const x = (event.clientX - rect.left) / Math.max(1, rect.width) * radarBox.width;
    const y = (event.clientY - rect.top) / Math.max(1, rect.height) * radarBox.height;
    let angle = Math.atan2(y - radarBox.centerY, x - radarBox.centerX) + Math.PI / 2;
    if (angle < 0) angle += Math.PI * 2;
    scheduleActiveIndex(Math.round(angle / (Math.PI * 2) * validAxes.length) % validAxes.length);
  };
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" && activeAxis && active !== null && onAxisActivate) {
      event.preventDefault();
      onAxisActivate(activeAxis, active);
      return;
    }
    const next = getLinearAnalyticsKeyIndex(event.key, active, validAxes.length);
    if (next === undefined) return;
    event.preventDefault();
    setActiveIndex(next);
  };

  const plot = (
    <div
      className={cn(analyticsClassNames.interactivePlot, "teum-radar-chart__plot")}
      role="group"
      aria-roledescription="interactive radar chart"
      aria-label={`${title}. ${validAxes.length} axes and ${renderedSeries.length} series.`}
      aria-describedby={instructionsId}
      tabIndex={validAxes.length && renderedSeries.length && !loading && !error ? 0 : -1}
      onPointerMove={handlePointerMove}
      onPointerLeave={clearActiveIndex}
      onKeyDown={handleKeyDown}
      onClick={() => { if (activeAxis && active !== null) onAxisActivate?.(activeAxis, active); }}
    >
      <p id={instructionsId} className="teum-sr-only">Use Arrow keys to inspect dimensions. Use Home and End to jump. Press Escape to clear.{onAxisActivate ? " Press Enter to open the active dimension." : ""}</p>
      <svg viewBox={`0 0 ${radarBox.width} ${radarBox.height}`} preserveAspectRatio="xMidYMid meet" aria-hidden="true" focusable="false">
        <g className="teum-radar-chart__grid">
          {[.25, .5, .75, 1].map((ratio) => <polygon key={ratio} points={radarPolygon(validAxes.map(() => ratio))} />)}
          {validAxes.map((axis, index) => {
            const end = radarPoint(index, validAxes.length);
            const label = radarPoint(index, validAxes.length, 1.18);
            return <g key={axis.id} data-active={active === index || undefined}><line x1={radarBox.centerX} y1={radarBox.centerY} x2={end.x} y2={end.y} /><text x={label.x} y={label.y} textAnchor={Math.abs(label.x - radarBox.centerX) < 8 ? "middle" : label.x < radarBox.centerX ? "end" : "start"}>{axis.label}</text></g>;
          })}
        </g>
        <g className="teum-radar-chart__series">
          {renderedSeries.map((item) => <polygon key={item.id} data-tone={item.tone} points={radarPolygon(item.normalized)} />)}
          {renderedSeries.flatMap((item) => item.normalized.map((ratio, index) => {
            const point = radarPoint(index, validAxes.length, ratio);
            return <circle key={`${item.id}-${validAxes[index]?.id}`} data-tone={item.tone} data-active={active === index || undefined} cx={point.x} cy={point.y} r={active === index ? 3.8 : 2.4} />;
          }))}
        </g>
      </svg>
      <div className="teum-radar-chart__legend" aria-hidden="true">{renderedSeries.map((item) => <span key={item.id} data-tone={item.tone}><i />{item.label}</span>)}</div>
      {activeAxis && active !== null && (
        <div className={cn(analyticsClassNames.tooltip, "teum-radar-chart__tooltip")} aria-hidden="true" style={{ "--teum-radar-x": `${radarPoint(active, validAxes.length, .78).x / radarBox.width * 100}%`, "--teum-radar-y": `${radarPoint(active, validAxes.length, .78).y / radarBox.height * 100}%` } as CSSProperties}>
          <strong>{activeAxis.label}</strong>
          {renderedSeries.map((item) => {
            const value = item.values[activeAxis.id];
            return <span key={item.id}><i data-tone={item.tone} />{item.label} <b>{typeof value === "number" ? valueFormatter(value, activeAxis, item) : "—"}</b></span>;
          })}
        </div>
      )}
    </div>
  );

  const table = (
    <table>
      <caption>{title} data</caption>
      <thead><tr><th scope="col">Dimension</th><th scope="col">Scale</th>{renderedSeries.map((item) => <th key={item.id} scope="col">{item.label}</th>)}</tr></thead>
      <tbody>{validAxes.map((axis) => <tr key={axis.id}><th scope="row">{axis.label}</th><td>{valueFormatter(axis.max, axis, renderedSeries[0] ?? { id: "scale", label: "Scale", values: {} })}</td>{renderedSeries.map((item) => { const value = item.values[axis.id]; return <td key={item.id}>{typeof value === "number" ? valueFormatter(value, axis, item) : "—"}</td>; })}</tr>)}</tbody>
    </table>
  );
  const summary = validAxes.length && renderedSeries.length ? `${title} compares ${renderedSeries.map((item) => item.label).join(", ")} across ${validAxes.length} dimensions.` : `${title} has no data.`;
  const activeDescription = activeAxis ? `${activeAxis.label}. ${renderedSeries.map((item) => { const value = item.values[activeAxis.id]; return `${item.label} ${typeof value === "number" ? valueFormatter(value, activeAxis, item) : "no value"}`; }).join(". ")}.` : "";

  return <AnalyticsFrame className={cn("teum-radar-chart", className)} title={title} description={description} height={height} summary={summary} plotLabel={`${title} radar chart`} plot={plot} table={table} loading={loading} empty={!validAxes.length || !renderedSeries.length ? empty : undefined} error={error} activeDescription={activeDescription} showDataByDefault={showDataByDefault} />;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-radar-chart__tooltip { left: clamp(78px, var(--teum-radar-x), calc(100% - 78px)); top: clamp(56px, var(--teum-radar-y), calc(100% - 54px)); transform: translate(-50%, -50%); }

.teum-radar-chart__grid polygon { fill: none; stroke: color-mix(in oklch, var(--teum-separator) 76%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; }

.teum-radar-chart__grid line { stroke: color-mix(in oklch, var(--teum-separator) 68%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; }

.teum-radar-chart__grid text { fill: var(--teum-fg-subtle); font-size: 9px; dominant-baseline: middle; }

.teum-radar-chart__grid g[data-active] text { fill: var(--teum-fg-default); font-weight: 590; }

.teum-radar-chart__grid g[data-active] line { stroke: color-mix(in oklch, var(--teum-fg-default) 36%, transparent); }

.teum-radar-chart__series polygon { fill: color-mix(in oklch, var(--teum-fg-default) 8%, transparent); stroke: var(--teum-fg-default); stroke-linejoin: round; stroke-width: 1.5; vector-effect: non-scaling-stroke; }

.teum-radar-chart__series polygon[data-tone="secondary"] { fill-opacity: .62; stroke-opacity: .62; stroke-dasharray: 4 3; }

.teum-radar-chart__series polygon[data-tone="tertiary"] { fill-opacity: .34; stroke-opacity: .38; stroke-dasharray: 1 3; }

.teum-radar-chart__series circle { fill: var(--teum-bg-surface); stroke: var(--teum-fg-default); stroke-width: 1.5; vector-effect: non-scaling-stroke; transition: r 120ms var(--teum-ease-out); }

.teum-radar-chart__series circle[data-tone="secondary"] { stroke-opacity: .62; }

.teum-radar-chart__series circle[data-tone="tertiary"] { stroke-opacity: .38; }

.teum-radar-chart__legend { position: absolute; right: 10px; bottom: 8px; display: flex; align-items: center; flex-wrap: wrap; justify-content: flex-end; gap: 8px; color: var(--teum-fg-subtle); font-size: 9px; }

.teum-radar-chart__legend span { display: inline-flex; align-items: center; gap: 4px; }

.teum-radar-chart__legend i,
.teum-radar-chart__tooltip i { width: 6px; height: 6px; flex: none; border-radius: 50%; background: var(--teum-fg-default); }

.teum-radar-chart__legend span[data-tone="secondary"] i,
.teum-radar-chart__tooltip i[data-tone="secondary"] { opacity: .62; }

.teum-radar-chart__legend span[data-tone="tertiary"] i,
.teum-radar-chart__tooltip i[data-tone="tertiary"] { opacity: .34; }

.teum-radar-chart__tooltip span { justify-content: flex-start; }

.teum-radar-chart__tooltip span b { margin-left: auto; }

@media (prefers-reduced-motion: reduce) {
.teum-radar-chart__series circle { transition-duration: 0ms; }
}
}
